from __future__ import annotations


def render_login_screen() -> str:
    return """<section id="loginScreen" class="login-screen"><div class="login-card"><div class="brand-small">AI Software Factory</div><div class="login-tabs"><button id="tabFounder" class="active" type="button">Platform Admin</button><button id="tabCustomer" type="button">Sign in / Sign up</button></div><div id="founderPanel"><h1>Platform Admin Login</h1><p class="muted">Sign in to enter Mission Control.</p><label>Founder email</label><input id="email" value="__FOUNDER_EMAIL__" autocomplete="username"><label>Password</label><input id="password" type="password" placeholder="FOUNDER_PASSWORD" autocomplete="current-password"><button id="loginBtn" type="button">Enter Mission Control</button><div id="loginError" class="error"></div><p class="muted">Auth status: __AUTH_STATUS__</p><p id="scriptStatus" class="small">Script loading...</p></div><div id="customerPanel" style="display:none"><h1 id="customerHeading">Sign in</h1><p class="muted">Sign in or create your own workspace.</p><div id="customerNameFields" style="display:none"><label>Full name</label><input id="customerFullName" autocomplete="name"><label>Organization name</label><input id="customerOrgName" autocomplete="organization"></div><label>Email</label><input id="customerEmail" autocomplete="username"><label>Password</label><input id="customerPassword" type="password" autocomplete="current-password"><button id="customerSubmitBtn" type="button">Sign in</button><div id="customerError" class="error"></div><p class="muted" id="customerSwitchMode">New here? <a id="customerSwitchLink" style="cursor:pointer;color:#93c5fd">Create an account</a></p></div></div></section>"""


def render_login_script() -> str:
    return """
var token=localStorage.getItem('mission_control_token')||'';
var customerMode='login';
function byId(id){return document.getElementById(id)}
function on(id,event,handler){var el=byId(id);if(el){el.addEventListener(event,handler)}}
function showApp(){byId('loginScreen').style.display='none';byId('app').style.display='grid'}
function showLogin(){byId('loginScreen').style.display='grid';byId('app').style.display='none'}
function post(url,body){return fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(function(r){return r.json()})}
async function login(){var err=byId('loginError');var btn=byId('loginBtn');err.textContent='';btn.disabled=true;btn.textContent='Signing in...';try{var data=await post('/mission-control/auth/login',{email:byId('email').value,password:byId('password').value});if(data.session&&data.session.token){token=data.session.token;localStorage.setItem('mission_control_token',token);showApp()}else{err.textContent=data.status||data.error||'Login failed'}}catch(e){err.textContent='Login request failed: '+e}finally{btn.disabled=false;btn.textContent='Enter Mission Control'}}
async function verifySession(){if(!token){showLogin();return}try{var data=await post('/mission-control/auth/session',{token:token});if(data.authenticated){showApp()}else{showLogin()}}catch(e){showLogin()}}
function switchTab(which){byId('tabFounder').classList.toggle('active',which==='founder');byId('tabCustomer').classList.toggle('active',which==='customer');byId('founderPanel').style.display=which==='founder'?'block':'none';byId('customerPanel').style.display=which==='customer'?'block':'none'}
function switchCustomerMode(){customerMode=customerMode==='login'?'signup':'login';byId('customerHeading').textContent=customerMode==='login'?'Sign in':'Create your workspace';byId('customerNameFields').style.display=customerMode==='signup'?'block':'none';byId('customerSubmitBtn').textContent=customerMode==='login'?'Sign in':'Create account';byId('customerSwitchMode').innerHTML=customerMode==='login'?'New here? <a id="customerSwitchLink" style="cursor:pointer;color:#93c5fd">Create an account</a>':'Already have an account? <a id="customerSwitchLink" style="cursor:pointer;color:#93c5fd">Sign in</a>';on('customerSwitchLink','click',switchCustomerMode);byId('customerError').textContent=''}
async function customerSubmit(){var err=byId('customerError');err.textContent='';var email=byId('customerEmail').value;var password=byId('customerPassword').value;try{var url=customerMode==='signup'?'/api/auth/register':'/api/auth/login';var body=customerMode==='signup'?{email:email,full_name:byId('customerFullName').value,password:password,organization_name:byId('customerOrgName').value}:{email:email,password:password};var response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});var data=await response.json();if(response.ok&&data.access_token){localStorage.setItem('customer_token',data.access_token);window.location.href='/customer/home'}else{err.textContent=data.detail||'Request failed'}}catch(e){err.textContent='Request failed: '+e}}
function bindLoginModule(){var ss=byId('scriptStatus');if(ss){ss.textContent='Script ready'};on('loginBtn','click',login);on('password','keydown',function(e){if(e.key==='Enter'){login()}});on('logoutBtn','click',function(){token='';localStorage.removeItem('mission_control_token');showLogin()});on('tabFounder','click',function(){switchTab('founder')});on('tabCustomer','click',function(){switchTab('customer')});on('customerSubmitBtn','click',customerSubmit);on('customerSwitchLink','click',switchCustomerMode);verifySession()}
"""
